/**
 * The `Paren::Lcurly` tokens `LATEX_SYMBOL_CLASS_INPUT` does NOT carry.
 *
 * `Utility.parens_hash` memoizes into `@@parens` keyed by lang and not by
 * `skipables`, and the first caller for `:latex` is the grammar —
 * `Constants.parenthesis` asks for `skipables: ["lcurly"]` while
 * `rule(:lparen)` is being built. So the transform reads a parens half
 * with no Lcurly, and these tokens fall through to a bare
 * `Math::Symbols::Symbol` carrying the text. Measured in a cold process:
 * `\\{x\\}` builds a `Fenced` opening on `Symbol("\\{")` and closing on
 * `Paren::Rcurly`.
 */
export const LATEX_SYMBOL_CLASS_SKIPPED_PARENS: readonly string[] = ["\\{"];

/**
 * The texts present in BOTH halves of `all_symbols_classes(:latex)`.
 * `symbols_hash.merge(parens_hash)` means the paren class wins each one;
 * emitted so a test can prove the emitted Map kept the winning side.
 */
export const LATEX_SYMBOL_CLASS_PAREN_OVERLAP: readonly string[] = [
  "&#x27e7;",
  "&#x27ea;",
  "&#x27eb;",
];

/**
 * `Constants::MATRICES` (`latex/constants.rb:121`): environment -> its
 * OPENING delimiter text, in the gem's order.
 *
 * Five values are nil. `symbols_class(nil, ...)` returns nil
 * (`utility.rb:213`), and the transform passes all three parens
 * positionally, so those tables are built with nil parens rather than
 * each subclass's own defaults — measured: `Table::Matrix.new(nil)`
 * defaults to round parens, `Table::Matrix.new(nil, nil, nil)` does not.
 */
export const LATEX_MATRICES: readonly (readonly [string, string | null])[] = [
  ["multline", null],
  ["Vmatrix", "\\Vert"],
  ["vmatrix", "|"],
  ["pmatrix", "("],
  ["Bmatrix", "{"],
  ["bmatrix", "["],
  ["matrix", null],
  ["split", null],
  ["align", null],
  ["array", null],
];

/**
 * `Constants::MATRICES_PARENTHESIS` (`:114`): OPENING delimiter ->
 * closing delimiter. The environment rules reach it through
 * `MATRICES[env]`, so the two tables compose.
 *
 * `\\Vert` maps to `]`, not to `\\Vert`. Transcribed, not corrected:
 * it is what `\\begin{Vmatrix}` builds in the gem.
 */
export const LATEX_MATRICES_PARENTHESIS: ReadonlyMap<string, string> = new Map([
  ["\\Vert", "]"],
  ["|", "|"],
  ["(", ")"],
  ["{", "}"],
  ["[", "]"],
]);

/**
 * `Constants::LEFT_RIGHT_PARENTHESIS` (`:181`): delimiter token ->
 * HTML entity, the table `left_right_objects` (`latex/utility.rb:101`)
 * converts a `\\left`/`\\right` delimiter through.
 *
 * The KEYS are also the grammar's `left_parens` and `right_parens`
 * alternatives (`LATEX_LEFT_RIGHT_PARENS` in `./parser-tables`); this
 * is the same table read for its values. A token the table lacks
 * yields nil, which becomes a `Left`/`Right` carrying nil.
 */
export const LATEX_LEFT_RIGHT_PARENTHESIS: ReadonlyMap<string, string> = new Map([
  ["\\backslash", "&#x5c;"],
  ["\\langle", "&#x2329;"],
  ["\\rangle", "&#x232a;"],
  ["\\lfloor", "&#x230a;"],
  ["\\rfloor", "&#x230b;"],
  ["\\lceil", "&#x2308;"],
  ["\\rceil", "&#x2309;"],
  ["\\lbrace", "&#x7b;"],
  ["\\rbrace", "&#x7d;"],
  ["\\lbrack", "&#x5b;"],
  ["\\rbrack", "&#x5d;"],
  ["\\Vert", "&#x2016;"],
  ["\\vert", "&#x7c;"],
  ["\\|", "&#x2016;"],
  ["\\}", "}"],
  ["\\{", "{"],
  ["(", "("],
  [")", ")"],
  ["<", "<"],
  [">", ">"],
  ["/", "/"],
  ["|", "|"],
  ["[", "["],
  ["]", "]"],
]);

/**
 * The symbol ids whose `is_nary_symbol?` is true, measured over every
 * `Math::Symbols::Symbol` descendant.
 *
 * `transform.rb:305` and `:319` ask a node the transform ALREADY BUILT
 * whether its `parameter_one` is one of these, and rebuild a `PowerBase`
 * into an `Nary` if so. `Core#is_nary_symbol?` returns nil for everything
 * else, so a miss is false rather than an error.
 */
export const LATEX_NARY_SYMBOL_IDS: readonly string[] = [
  "Bigwedge",
  "Clockoint",
  "Cntclockoint",
  "Coprod",
  "Dint",
  "Duni",
  "Iiiint",
  "Iiint",
  "Iint",
  "Intclockwise",
  "Oiiint",
  "Oiint",
  "Oint",
];

