/**
 * Symbol ids whose `separate_table` is true with NO value — the
 * `is_a?(Ampersand)` arm of `Symbol#separate_table`
 * (`symbols/symbol.rb:167`). A CLASSED symbol has `@value` nil, so this
 * is the arm that fires for `&` once `symbols_class` has resolved it.
 */
export const LATEX_SEPARATE_TABLE_SYMBOL_IDS: readonly string[] = ["Ampersand"];

/**
 * The `value` strings that make a BARE `Math::Symbols::Symbol` answer
 * `separate_table` — the other arm of the same predicate, reached when
 * `symbols_class` missed and kept the text. Measured by probing every
 * text the latex symbol table can produce.
 */
export const LATEX_SEPARATE_TABLE_VALUES: readonly string[] = ["&", "\\\\"];

/**
 * The `value` strings that make a bare `Math::Symbols::Symbol` answer
 * `linebreak?` (`symbols/symbol.rb:172`) — the test `organize_table`
 * uses to close a row rather than just a cell. `Math::Function::Linebreak`
 * answers true unconditionally and is handled by kind, not by value.
 */
export const LATEX_LINEBREAK_VALUES: readonly string[] = ["\\\\"];

/**
 * The symbol classes `latex/transform.rb` and `latex/utility.rb` name
 * as literals, mapped to the ids the port carries: `Hline`
 * (`hline_row?`), `Minus` (`filter_table_data`), `Paren::Vert`
 * (`table_separator`), `Paren::Lcurly`/`Paren::Rcurly`
 * (`latex_table_curly_paren` and the `binom` special case) and
 * `ThreePerEmSpace` (`transform.rb:38`).
 */
export const LATEX_NAMED_SYMBOLS: ReadonlyMap<string, string> = new Map([
  ["hline", "Hline"],
  ["minus", "Minus"],
  ["vert", "Paren::Vert"],
  ["lcurly", "Paren::Lcurly"],
  ["rcurly", "Paren::Rcurly"],
  ["threePerEmSpace", "ThreePerEmSpace"],
]);

